// The synthetic sixty-cut episode (#314): a generator, not data. Nothing about
// the episode is tracked; the project, its cuts, its transitions and its images
// are produced at run time into a scratch directory the run owns and removes.
//
// Every title and label here is structural. A cut is named by where it sits in
// the sequence, a beat by its index, and an image is a grid and a few rectangles
// at panel size. The images depict nothing and were never generated by a model.
// The text is not a story. That is the whole point: what this fixture proves is
// that Toony's stages run in order at sixty cuts, how long each takes and how
// much each emits, and nothing about whether the result is a webtoon.

import { createCanvas } from "@napi-rs/canvas";
import { EPISODE_PLAN_FORMAT_VERSION, type EpisodePlan } from "@toony/export";
import { buildInitialProject } from "@toony/project-io";
import {
  type Cut,
  type Project,
  SHOT_TYPES,
  type ShotType,
  STANDARD_CANVAS_WIDTH_PX,
  type Transition,
  type TransitionType,
} from "@toony/schema";

/** The scale this fixture is pinned at. The run reads it back and refuses anything else. */
export const SIXTY = 60;
export const CUTS_PER_BEAT = 3;
export const BEAT_COUNT = SIXTY / CUTS_PER_BEAT;
export const EPISODE_ID = "ep-001";
export const PROJECT_NAME = "sixty-cut-structure";
/** Source images are drawn at the stitched and platform export width, so no export resamples them. */
export const SOURCE_WIDTH_PX = 1200;

/**
 * The limits clause (#314, contract default 3). It is reproduced verbatim in the
 * run's output, in `docs/SCALE_FIXTURE.md` and in the pull request that landed
 * it, and the run asserts its own output carries it.
 */
export const LIMITS_CLAUSE =
  "This fixture is synthetic. It proves that Toony's stages run in order at sixty cuts, how long each takes, and how much each emits. It proves nothing about whether the result is a webtoon. Its images are not artwork. They were never drawn and were never generated by a model. Its text is not a story. No result from this fixture is visual acceptance, quality acceptance, or evidence that Toony can produce an episode. It does not satisfy #243 and it does not change what `docs/CAPSTONE.md` certifies.";

/**
 * One beat: three cuts at one declared shape, two identical gaps inside it, and
 * the gap it opens on. Twenty of these, none alike, so no geometry the page
 * measures is a constant: the shapes span 0.58 to 1.95 widths, the inside gaps
 * 44 to 324 px, the opening gaps 360 to 522 px across nine structural kinds.
 */
export interface BeatSpec {
  index: number;
  /** `Cut.panelAspect` for every cut of the beat. */
  aspect: number;
  /** The gap between the beat's cuts, px on the standard column. */
  gap: number;
  /** The gap that leads into the beat; the first beat opens on none. */
  open: { type: TransitionType; height: number } | null;
}

const ASPECTS = [
  0.62, 1.38, 0.95, 1.8, 1.12, 0.75, 1.55, 1.95, 0.88, 1.25, 1.68, 0.7, 1.02, 1.85, 1.18, 0.58,
  1.45, 0.82, 1.32, 0.66,
] as const;

/** Inside gaps, every pair more than the lint's 12 px monotony tolerance apart. */
const INSIDE_GAPS = [
  44, 72, 58, 100, 86, 128, 114, 156, 142, 184, 170, 212, 198, 240, 226, 268, 254, 296, 282, 324,
] as const;

/** The structural kinds an opening gap cycles through: no text, no card, each a drawn band or a gutter. */
const OPENING_KINDS: readonly TransitionType[] = [
  "gutter",
  "fade",
  "black_band",
  "void",
  "color_field",
  "scene-break",
  "hard-cut",
  "palette_shift",
  "desaturate_repeat",
];

export function beatSpecs(): BeatSpec[] {
  return Array.from({ length: BEAT_COUNT }, (_, index) => ({
    index,
    aspect: ASPECTS[index] as number,
    gap: INSIDE_GAPS[index] as number,
    open:
      index === 0
        ? null
        : {
            type: OPENING_KINDS[(index - 1) % OPENING_KINDS.length] as TransitionType,
            height: 360 + (index - 1) * 9,
          },
  }));
}

/** Cut k's shot type: a stride of two over the five kinds, so no two neighbours share one. */
export function shotTypeAt(cutIndex: number): ShotType {
  return SHOT_TYPES[(cutIndex * 2) % SHOT_TYPES.length] as ShotType;
}

export function cutId(cutIndex: number): string {
  return `cut-${String(cutIndex + 1).padStart(3, "0")}`;
}

function transition(id: string, type: TransitionType, gutterHeight: number): Transition {
  return {
    id,
    type,
    gutterHeight,
    text: null,
    sfx: null,
    agentNote: null,
    humanNote: null,
    image: null,
    reviewStatus: "draft",
  };
}

/** The sixty-cut project, in memory: sixty cuts, fifty-nine transitions, no lettering. */
export function buildSixtyCutProject(): Project {
  const project = buildInitialProject(PROJECT_NAME);
  const bundle = project.episodes[0];
  if (bundle === undefined) throw new Error("the initial project has no episode");
  const cuts: Cut[] = [];
  const transitions: Transition[] = [];
  const sequence: Array<{ type: "cut"; id: string } | { type: "transition"; id: string }> = [];
  let cutIndex = 0;
  let transitionIndex = 0;
  for (const beat of beatSpecs()) {
    if (beat.open !== null) {
      const id = `tr-${String(++transitionIndex).padStart(3, "0")}`;
      transitions.push(transition(id, beat.open.type, beat.open.height));
      sequence.push({ type: "transition", id });
    }
    for (let i = 0; i < CUTS_PER_BEAT; i++) {
      if (i > 0) {
        const id = `tr-${String(++transitionIndex).padStart(3, "0")}`;
        transitions.push(transition(id, "gutter", beat.gap));
        sequence.push({ type: "transition", id });
      }
      const id = cutId(cutIndex);
      cuts.push({
        id,
        image: null,
        imagePrompt: "",
        negativePrompt: "",
        panelAspect: beat.aspect,
        shotType: shotTypeAt(cutIndex),
      });
      sequence.push({ type: "cut", id });
      cutIndex++;
    }
  }
  bundle.episode.id = EPISODE_ID;
  bundle.episode.title = "Sixty-cut structure";
  bundle.episode.sequence = sequence;
  bundle.cuts = cuts;
  bundle.transitions = transitions;
  bundle.lettering = [];
  return project;
}

/** The same structure as beats with lengths, for `toony plan --spec`. */
export function sixtyCutPlan(): EpisodePlan {
  return {
    planFormat: EPISODE_PLAN_FORMAT_VERSION,
    name: "sixty-cut structure",
    referenceWidth: STANDARD_CANVAS_WIDTH_PX,
    beats: beatSpecs().map((beat) => ({
      label: `beat-${String(beat.index + 1).padStart(2, "0")}`,
      cuts: CUTS_PER_BEAT,
      panelAspect: beat.aspect,
      gap: { type: "gutter", gutterHeight: beat.gap },
      ...(beat.open === null
        ? {}
        : { openWith: { type: beat.open.type, gutterHeight: beat.open.height } }),
    })),
  };
}

/**
 * A structure image at panel size: a grey ramp, a grid, and three rectangles at
 * three luminances, placed by the cut's index. It passes the shipped image
 * checks (`image/blank`, `image/dark`, `image/low-contrast`) because it is not
 * uniform, not dark and not flat, and it depicts nothing. Its height is the
 * declared shape to the pixel, so `cut/panel-aspect-mismatch` has nothing to say.
 */
export function structureImagePng(cutIndex: number, aspect: number): Buffer {
  const width = SOURCE_WIDTH_PX;
  const height = Math.round(width * aspect);
  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext("2d");
  const top = 96 + (cutIndex % 7) * 8;
  const bottom = 208 - (cutIndex % 5) * 6;
  const ramp = ctx.createLinearGradient(0, 0, 0, height);
  ramp.addColorStop(0, grey(top));
  ramp.addColorStop(1, grey(bottom));
  ctx.fillStyle = ramp;
  ctx.fillRect(0, 0, width, height);
  ctx.fillStyle = grey(64);
  for (let x = 48; x < width; x += 48) ctx.fillRect(x, 0, 2, height);
  for (let y = 48; y < height; y += 48) ctx.fillRect(0, y, width, 2);
  const slot = cutIndex % 4;
  const block = (fx: number, fy: number, fw: number, fh: number, level: number): void => {
    ctx.fillStyle = grey(level);
    ctx.fillRect(
      Math.round(width * fx),
      Math.round(height * fy),
      Math.round(width * fw),
      Math.round(height * fh),
    );
  };
  block(0.08 + slot * 0.05, 0.08, 0.3, 0.18, 236);
  block(0.55 - slot * 0.05, 0.34, 0.32, 0.22, 40);
  block(0.18, 0.66 + slot * 0.03, 0.5, 0.14, 150);
  return canvas.toBuffer("image/png");
}

function grey(level: number): string {
  const hex = Math.max(0, Math.min(255, Math.round(level)))
    .toString(16)
    .padStart(2, "0");
  return `#${hex}${hex}${hex}`;
}
